// ConvertGoStructToAvro takes a filename (including path) and a struct name,
// reads the struct definition from the specified file, generates an Avro schema,
// and writes the schema to a new file with the ".avsc" extension.
func ConvertGoStructToAvro(srcFilename string, structName string) error {
	var err error
	if srcFilename == "" || structName == "" {
		return fmt.Errorf("both 'srcFilename' and 'structName' must be provided")
	}

	// Read the struct definition from the source file
	structDefinition, err := ioutil.ReadFile(srcFilename)
	if err != nil {
		return fmt.Errorf("failed to read struct definition: %v", err)
	}
	defer func() { _ = os.Remove(srcFilename) }()

	// Parse the struct definition
	parsedStruct, err := schema.Parse(structDefinition)
	if err != nil {
		return fmt.Errorf("failed to parse struct definition: %v", err)
	}

	// Generate the Avro schema using single-flight for concurrency
	flight := singleflight.Group()
	err = flight.Do(context.Background(), "convert_struct_to_avro", func(ctx context.Context) error {
		schemaBytes, err := schema.Generate(parsedStruct)
		if err != nil {
			return fmt.Errorf("failed to generate Avro schema: %v", err)
		}

		// Write the generated Avro schema to a temporary file
		tmpFilePath := filepath.Join(filepath.Dir(srcFilename), "tmp_" + structName+".avsc")
		if err := ioutil.WriteFile(tmpFilePath, schemaBytes, 0644); err != nil {
			return fmt.Errorf("failed to write Avro schema to file: %v", err)
		}

		// Return the temp file's path so we can delete it later if needed
		return nil
	})
	if err != nil {
		return fmt.Errorf("error generating Avro schema: %v", err)
	}

	fmt.Printf("Generated Avro schema at: %s\n", tmpFilePath)

	return nil
}

func main() {
	srcFilename := "./path/to/your/srcfile.go" // Replace with your actual source file path
	structName := "YourStruct"               // Replace with your struct name

	err := ConvertGoStructToAvro(srcFilename, structName)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}
```

